//
// Arguments:
//   - serviceName: Service name
//   - id: Id
//   - deploymentID: Deployment ID
//
// Requires the IAM action webHosting:apiovh:website/deployment/get.
func (s *Service) GetWebsiteDeployment(ctx context.Context, serviceName string, id int, deploymentID int) (*HostingWebWebsiteDeployment, error) {
	return ovh.Call[*HostingWebWebsiteDeployment](ctx, s.c, &ovh.Request{Operation: opGetWebsiteDeployment, Method: http.MethodGet, Path: ovh.Path("/v1/hosting/web/{serviceName}/website/{id}/deployment/{deploymentId}", "serviceName", serviceName, "id", id, "deploymentId", deploymentID)})
}

// AllWebsiteDeployments iterates over every object ListWebsiteDeployments lists, fetching each one with
// GetWebsiteDeployment only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllWebsiteDeployments(ctx context.Context, serviceName string, id int) iter.Seq2[*HostingWebWebsiteDeployment, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]int, error) {
			return s.ListWebsiteDeployments(ctx, serviceName, id)
		},
		func(ctx context.Context, listedID int) (*HostingWebWebsiteDeployment, error) {
			return s.GetWebsiteDeployment(ctx, serviceName, id, listedID)
		})
}

